scripts.integer_division_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Compute integer division for each pair and sum
    total = sum(a // b for a, b in zip(A, B))

    return float(total)

scripts.lcg_update:
def solve(inputs: dict) -> float:
    seed = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    x = seed
    for _ in range(k):
        x = ((a * x) + b) % m

    return float(x)
